class Sampler {
  constructor() { this._reservoir=[]; this._n=0; }
  add(v) { this._n++; if(this._reservoir.length<1024) { this._reservoir.push(v); } else { const j=Math.floor(Math.random()*this._n); if(j<1024) this._reservoir[j]=v; } }
  count() { return this._n; }
  percentile(p) { if(!this._reservoir.length) return 0; const s=[...this._reservoir].sort((a,b)=>a-b); const i=Math.min(Math.floor(p/100*(s.length-1)),s.length-1); return s[i]; }
}
module.exports={Sampler};
EOF
